<script setup lang="ts">import { colorPickerSwatchClassName } from '@fex-design/styles/color-picker';import { cn } from '@fex/utils';import { computed,useAttrs } from 'vue';import { useColorPicker } from './context';defineOptions({inheritAttrs:false});const props=defineProps<{color?:string}>(),attrs=useAttrs(),picker=useColorPicker();const colorValue=computed(()=>props.color??picker.snapshot.value.value?.toString('rgb')??'transparent')</script><template><span v-bind="attrs" :data-empty="!picker.snapshot.value.value||undefined" :class="cn(colorPickerSwatchClassName,attrs.class as string|undefined)" :style="[{'--color-picker-color':colorValue},attrs.style]" /></template>
